// Hand-derived minimal type surface of @cancjs/coroutine/iter (cancIter namespace) for fixtures.

import { ICancelablePromiseOptions } from '@cancjs/promise';
import { IGeneratorLikeFn, TEachSource, TForAwaitCallback } from '@cancjs/coroutine';

declare const awaitedSymbol: unique symbol;
type TAwaited<T = any> = { [awaitedSymbol]: T };

export declare const awaited: <T = any>(value: T | TAwaited<T>) => TAwaited<T>;

export declare function cancIterAwait<T>(
 value: Promise<T> | T,
): Generator<TAwaited<Awaited<T>>, Awaited<T>, Awaited<T>>;

export type AsyncIterResult<E, R = void> = Generator<E | TAwaited<any>, R, any>;

export declare function cancIterAsync<TYield, TReturn, TArgs extends any[], TThis = any>(
 genFn: (this: TThis, ...args: TArgs) => Generator<TYield, TReturn, any>,
 options?: ICancelablePromiseOptions,
): (this: TThis, ...args: TArgs) => AsyncGenerator<Exclude<TYield, TAwaited<any>>, TReturn>;

interface ICancIterForAwait {
 <T>(source: TEachSource<T>, cb: TForAwaitCallback<T>): Generator<TAwaited<any>, void, any>;
 toArray<T>(source: TEachSource<T>): Generator<TAwaited<any>, T[], any>;
}
export declare const cancIterForAwait: ICancIterForAwait;

export declare function cancIterDelegate<T>(
 source: TEachSource<T>,
): Generator<T | TAwaited<any>, void, any>;

export {
 cancIterAsync as async,
 cancIterAwait as await,
 cancIterForAwait as forAwait,
 cancIterDelegate as delegate,
};
